{
  "items": [
    {
      "name": "MvPolynomial.IsWeightedHomogeneous.pderiv",
      "module_name": "Mathlib.RingTheory.MvPolynomial.EulerIdentity",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {σ : Type u_2} {M : Type u_3} [inst : CommSemiring R] {φ : MvPolynomial σ R}\n  [inst_1 : AddCancelCommMonoid M] {w : σ → M} {n n' : M} {i : σ},\n  MvPolynomial.IsWeightedHomogeneous w φ n →\n    n' + w i = n → MvPolynomial.IsWeightedHomogeneous w ((MvPolynomial.pderiv i) φ) n'"
    },
    {
      "name": "iInf",
      "module_name": "Mathlib.Order.SetNotation",
      "kind": "definition",
      "type": "{α : Type u} → {ι : Sort v} → [InfSet α] → (ι → α) → α"
    },
    {
      "name": "ciInf_le'",
      "module_name": "Mathlib.Order.ConditionallyCompleteLattice.Indexed",
      "kind": "theorem",
      "type": "∀ {α : Type u_1} {ι : Sort u_4} [inst : ConditionallyCompleteLinearOrderBot α] (f : ι → α) (i : ι), iInf f ≤ f i"
    },
    {
      "name": "Finset.inf_le_centerMass",
      "module_name": "Mathlib.Analysis.Convex.Combination",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {ι : Type u_5} {α : Type u_7} [inst : Field R] [inst_1 : AddCommGroup α] [inst_2 : LinearOrder α]\n  [inst_3 : Module R α] [inst_4 : LinearOrder R] [IsOrderedAddMonoid α] [PosSMulMono R α] {s : Finset ι} {f : ι → α}\n  {w : ι → R} (hw₀ : ∀ i ∈ s, 0 ≤ w i) (hw₁ : 0 < ∑ i ∈ s, w i), s.inf' ⋯ f ≤ s.centerMass w f"
    },
    {
      "name": "AddMonoidAlgebra.le_inf_support_finset_prod",
      "module_name": "Mathlib.Algebra.MonoidAlgebra.Degree",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {A : Type u_3} {T : Type u_4} {ι : Type u_6} [inst : SemilatticeInf T] [inst_1 : OrderTop T]\n  [inst_2 : CommSemiring R] [inst_3 : AddCommMonoid A] [inst_4 : AddCommMonoid T] [AddLeftMono T] [AddRightMono T]\n  {degt : A → T},\n  0 ≤ degt 0 →\n    (∀ (a b : A), degt a + degt b ≤ degt (a + b)) →\n      ∀ (s : Finset ι) (f : ι → AddMonoidAlgebra R A), ∑ i ∈ s, (f i).support.inf degt ≤ (∏ i ∈ s, f i).support.inf degt"
    }
  ]
}

